<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {Building2,GraduationCap,Users,BriefcaseBusiness,Clock3,Handshake,ArrowRight,CheckCheck,Trophy} from '@lucide/vue'
import content from '../content.json'
import type {ApiResult,Player,RoomState,Undergraduate} from '../types'
import ScholarResume from './ScholarResume.vue'
import ScholarPortrait from './ScholarPortrait.vue'
const props=defineProps<{player:Player;state:RoomState;busy:boolean;now:number;perform:(a:string,p?:Record<string,unknown>)=>Promise<ApiResult|undefined>}>()
const section=ref(props.player.scene==='enterprise'?'company':'undergrad'),mode=ref('self'),worker=ref(''),share=ref(30),team=ref('picnic'),contest=ref('bridge'),teamStudents=ref<string[]>([]),squad=ref<string[]>([]),coach=ref(''),cv=ref<Undergraduate|null>(null)
watch(()=>props.player.scene,s=>section.value=s==='enterprise'?'company':'undergrad')
const available=computed(()=>props.player.students.filter(s=>!s.graduatedAt&&s.availability.canWork))
const partner=computed(()=>Object.values(props.state.players).find(p=>p.id!==props.player.id))
const jobs=computed(()=>Object.values(props.state.players).flatMap(p=>p.world.jobs.filter(j=>p.id===props.player.id||j.partnerId===props.player.id).map(j=>({...j,ownerId:p.id}))).sort((a,b)=>b.createdAt-a.createdAt))
const ongoing=(kind:string)=>props.player.world.jobs.some(j=>j.kind===kind&&['working','invited','ready'].includes(j.status))
const teamDef=computed(()=>content.world.teams.find(t=>t.id===team.value)!)
const contestDef=computed(()=>content.world.contests.find(t=>t.id===contest.value)!)
const teamCost=computed(()=>teamDef.value.base+teamDef.value.perStudent*teamStudents.value.length)
const freeWork=computed(()=>!props.player.contractWork&&!props.player.worldWork)
const names=(ids:string[]=[])=>ids.map(id=>props.player.students.find(s=>s.id===id)?.name||props.player.world.undergraduates.find(s=>s.id===id)?.name).filter(Boolean).join('、')
const domain=(d:string)=>d==='civil'?'智能建造':d==='air'?'低空经济':'空地交叉'
const clock=(at:number|undefined)=>!at?'等待进展':at<=props.now?'正在同步':Math.ceil((at-props.now)/60000)>=60?'约 '+Math.ceil((at-props.now)/3600000)+' 小时':'约 '+Math.ceil((at-props.now)/60000)+' 分钟'
const status:Record<string,string>={working:'准备中',invited:'等待搭子回复',ready:'准备完成',completed:'已留档',cancelled:'已撤回'}
function start(id:string){return props.perform('world_company_start',{id,mode:mode.value,studentId:worker.value,share:share.value})}
</script>
<template><section class="world-hub"><header class="world-intro"><Building2 :size="29"/><div><span class="small-label">BEYOND THE LAB · 二级园区已开放</span><h2>把研究带出去，也把生活带回来。</h2><p>企业会看成果，本科生会来报名。声望越高，主动联系越多，合作预算也会增加。</p></div></header>
 <div class="research-subnav"><button :class="{active:section==='company'}" @click="section='company'"><BriefcaseBusiness :size="15"/>企业合作</button><button :class="{active:section==='undergrad'}" @click="section='undergrad'"><GraduationCap :size="15"/>本科生与比赛</button><button :class="{active:section==='team'}" @click="section='team'"><Users :size="15"/>课题组团建</button><button :class="{active:section==='jobs'}" @click="section='jobs'"><Clock3 :size="15"/>在办与记录</button></div>
 <template v-if="section==='company'"><div class="world-contact-note"><b>科研声望 {{ player.rep }}</b><span>下一次企业联系：{{ clock(player.world.nextCompanyAt) }}</span></div><p class="muted">签下合作需要投入材料和实际时间，验收后才收经费。请学生协助会分走他们自己的研究精力。</p><div class="world-form"><label>准备怎么做<select v-model="mode"><option value="self">自己推进 · 基准 6 小时</option><option value="student">请学生协助 · 随研究节奏推进</option><option value="outsource">经费外协 · 基准 2 小时</option><option value="coop">邀请搭子 · 基准 4 小时</option></select></label><label v-if="mode==='student'">本组同学<select v-model="worker"><option value="">选择一位同学</option><option v-for="s in available" :key="s.id" :value="s.id">{{ s.name }} · {{ s.moodText }}</option></select></label><label v-if="mode==='coop'">给 {{ partner?.profile.name||'搭子' }} 的分账<select v-model.number="share"><option v-for="n in [10,20,30,40,50]" :key="n" :value="n">{{ n }}%</option></select></label></div><p v-if="mode==='coop'" class="muted">邀请先送达，搭子接受后才消耗你的行动力、材料费并占用双方工作位。</p><p v-if="!freeWork&&['self','coop'].includes(mode)" class="muted">你的工作位正忙，可以选择学生协助或经费外协。</p>
  <article v-for="o in player.world.offers?.filter(o=>o.status==='open')" :key="o.id" class="world-offer"><span class="small-label">{{ domain(o.domain) }} · {{ o.company }}</span><h3>{{ o.title }}</h3><div class="world-money"><span>交付后收入 <b>{{ o.total }}</b></span><span>开工支出 <b>{{ mode==='outsource'?Math.ceil(o.total*.4):o.cost }}</b></span></div><button class="primary" :disabled="busy||ongoing('company')||player.funds<(mode==='outsource'?Math.ceil(o.total*.4):o.cost)||mode!=='coop'&&player.energy<1||mode==='student'&&!worker||['self','coop'].includes(mode)&&!freeWork||mode==='coop'&&!partner" @click="start(o.id);section='jobs'">{{ mode==='coop'?'发出合作邀请':'安排合作 · 1 行动力' }}<ArrowRight :size="15"/></button></article><p v-if="!player.world.offers?.some(o=>o.status==='open')" class="empty-note">先去园区交流需求，或者等下一封主动联系。没有需要赶的倒计时。</p></template>
 <template v-else-if="section==='undergrad'"><div class="world-contact-note"><b>本科生小队 {{ player.world.undergraduates.length }} / 12</b><span>下一轮报名：{{ clock(player.world.nextUndergradAt) }}</span></div><div class="section-title"><h2>来报名的同学</h2><span>可以先看经历再决定</span></div><div class="undergrad-grid"><button v-for="u in player.world.applicants?.filter(u=>!u.accepted)" :key="u.id" @click="cv=u"><ScholarPortrait :seed="u.id" :size="46" :label="u.name+'头像'"/><span><b>{{ u.name }}</b><small>{{ u.year }} · {{ domain(u.domain) }}</small></span><ArrowRight :size="15"/></button></div><p v-if="!player.world.applicants?.some(u=>!u.accepted)" class="empty-note">作品与声望会吸引新同学。也可以摇骰子去创新工坊交流。</p><div class="section-title"><h2>一起做一项可交付作品</h2></div><div class="world-form"><label>比赛<select v-model="contest"><option v-for="c in content.world.contests" :key="c.id" :value="c.id">{{ c.name }}</option></select></label><label>指导准备<select v-model="coach"><option value="">我来带队 · 占用个人工作位</option><option v-for="s in available" :key="s.id" :value="s.id">{{ s.name }} 协助准备</option></select></label></div><p class="muted">{{ contestDef.cost }} 经费 · 基准 {{ contestDef.hours }} 小时准备 · 最高奖金 {{ contestDef.prize }}。专业契合、同学的积累与老师声望会影响表现，也可能没有获奖。</p><div class="world-student-choices"><label v-for="u in player.world.undergraduates" :key="u.id"><input v-model="squad" type="checkbox" :value="u.id" :disabled="squad.length>=4&&!squad.includes(u.id)"/><b>{{ u.name }}</b><small>{{ domain(u.domain) }}</small><button class="text-button" type="button" @click="cv=u">简历</button></label></div><button class="primary" :disabled="busy||ongoing('competition')||!squad.length||player.funds<contestDef.cost||player.energy<1||!coach&&!freeWork" @click="perform('world_competition_start',{option:contest,undergradIds:squad,studentId:coach||undefined});section='jobs'"><Trophy :size="16"/>安排 1–4 人小队 · 1 行动力</button><p class="gentle-footer">完成后查看比赛结果，奖金、经费支出与经历都会落到真实存档里。</p></template>
 <template v-else-if="section==='team'"><h2>今天一起离开工位吧。</h2><p class="muted">团建期间暂停参与同学自己的研究。回来后，近况与交流关系会得到改善，并留下共同经历。</p><div class="world-form"><label>这次去哪<select v-model="team"><option v-for="t in content.world.teams" :key="t.id" :value="t.id">{{ t.name }} · {{ t.hours }} 小时</option></select></label></div><div class="world-student-choices"><label v-for="s in available" :key="s.id"><input v-model="teamStudents" type="checkbox" :value="s.id" :disabled="teamStudents.length>=8&&!teamStudents.includes(s.id)"/><b>{{ s.name }}</b><small>{{ s.moodText }}</small></label></div><p class="muted">基础 {{ teamDef.base }} + 每人 {{ teamDef.perStudent }}，共 {{ teamCost }} 经费。</p><button class="primary" :disabled="busy||ongoing('team')||!teamStudents.length||player.funds<teamCost||player.energy<1" @click="perform('world_team_start',{option:team,studentIds:teamStudents});section='jobs'"><Users :size="16"/>带同学出发 · 1 行动力</button></template>
 <template v-else><p v-if="!jobs.length" class="empty-note">企业合作、比赛和团建都会在这里留下记录。</p><article v-for="j in jobs.slice(0,14)" :key="j.id" class="world-job"><span class="small-label">{{ status[j.status] }} · {{ j.kind==='company'?'企业合作':j.kind==='team'?'团建':'本科生比赛' }}</span><h3>{{ j.title }}</h3><p v-if="j.status==='working'">{{ j.stalled?'目前还在等新的进展，可以聊聊或由老师接手。':clock(j.dueAt)+'后可查看结果' }}<span v-if="j.studentName"> · {{ j.studentName }}协助</span><span v-if="j.studentIds"> · {{ names(j.studentIds) }}</span></p><p v-if="j.paid">已支出 {{ j.paid }} 经费<span v-if="j.partnerId"> · {{ state.players[j.partnerId]?.profile.name }} 分账 {{ j.share }}%</span></p><p v-if="j.result">{{ j.result }}</p><p v-if="j.undergradIds?.length">小队：{{ names(j.undergradIds) }}</p><div class="world-job-actions"><button v-if="j.status==='ready'" class="primary" :disabled="busy" @click="perform('world_claim',{id:j.id})"><CheckCheck :size="16"/>{{ j.kind==='company'?'提交交付，收取经费':j.kind==='competition'?'查看比赛结果':'记录这次团建' }}</button><template v-if="j.status==='invited'"><template v-if="j.partnerId===player.id"><button class="primary" :disabled="busy||!freeWork" @click="perform('world_respond',{id:j.id,accept:true})"><Handshake :size="15"/>接受合作</button><button class="secondary" :disabled="busy" @click="perform('world_respond',{id:j.id,accept:false})">这次先不了</button></template><button v-else class="secondary" :disabled="busy" @click="perform('world_cancel_invite',{id:j.id})">撤回邀请</button></template><button v-if="j.studentId&&j.status==='working'&&j.ownerId===player.id" class="secondary" :disabled="busy||!freeWork" @click="perform('world_takeover',{id:j.id})">老师接手，保留进度</button></div></article></template>
 <div v-if="cv" class="resume-overlay" role="dialog" aria-modal="true" @keydown.esc="cv=null" :aria-label="cv.name+'本科生简历'" @click.self="cv=null"><section class="resume-dialog"><button class="text-button close-resume" @click="cv=null">返回本科生小队</button><ScholarResume :name="cv.name" :resume="cv.resume"/><h3 v-if="cv.experiences?.length">参加过的作品与比赛</h3><p v-for="(x,i) in cv.experiences" :key="i">{{ x.title }} · {{ x.result }}</p><button v-if="!cv.accepted" class="primary wide" :disabled="busy||player.world.undergraduates.length>=12" @click="perform('world_undergrad_accept',{id:cv.id});cv=null">欢迎加入本科生小队</button></section></div>
 </section></template>
